public class Solution {
  /**
   * 并查集：按大小组并 + 迭代 find + 路径压缩（两趟：先找根，再把路径挂到根）。
   * 组根恒为"组内最小 id"，所以合并时显式比较两个根，取小者当根 —— 结果与输入顺序无关。
   */
  public static int[] snapshotGroups(int n, int[] evidenceA, int[] evidenceB) {
    if (evidenceA.length != evidenceB.length) {
      throw new IllegalArgumentException("evidence arrays must be parallel");
    }
    int[] parent = new int[n];
    int[] size = new int[n];
    for (int v = 0; v < n; v++) {
      parent[v] = v;
      size[v] = 1;
    }
    for (int k = 0; k < evidenceA.length; k++) {
      int a = evidenceA[k];
      int b = evidenceB[k];
      if (a < 0 || a >= n || b < 0 || b >= n) {
        throw new IllegalArgumentException("evidence endpoint out of range");
      }
      int ra = find(parent, a);
      int rb = find(parent, b);
      if (ra == rb) continue;                    // 重复/自证据：幂等
      int keep = Math.min(ra, rb);               // 代表元 = 组内最小 id
      int drop = Math.max(ra, rb);
      parent[drop] = keep;
      size[keep] += size[drop];
    }
    int[] out = new int[n];
    for (int v = 0; v < n; v++) out[v] = find(parent, v);
    return out;
  }

  /** 迭代 find：链式证据下递归会 StackOverflowError（栈深度 = 链长）。 */
  static int find(int[] parent, int x) {
    int root = x;
    while (parent[root] != root) root = parent[root];
    while (parent[x] != root) {
      int next = parent[x];
      parent[x] = root;
      x = next;
    }
    return root;
  }
}

runner.naiveSolution:
public class Solution {
  // 朴素：不做按秩/按最小合并，永远把 b 的根挂到 a 的根下，find 也不压缩。
  // 代表元由"证据出现的顺序"决定 -> 反向证据给出不同的组根，落盘指纹不稳定。
  public static int[] snapshotGroups(int n, int[] evidenceA, int[] evidenceB) {
    if (evidenceA.length != evidenceB.length) {
      throw new IllegalArgumentException("evidence arrays must be parallel");
    }
    int[] parent = new int[n];
    for (int v = 0; v < n; v++) parent[v] = v;
    for (int k = 0; k < evidenceA.length; k++) {
      int a = evidenceA[k];
      int b = evidenceB[k];
      if (a < 0 || a >= n || b < 0 || b >= n) {
        throw new IllegalArgumentException("evidence endpoint out of range");
      }
      int ra = find(parent, a);
      int rb = find(parent, b);
      if (ra != rb) parent[rb] = ra;             // 只看证据方向
    }
    int[] out = new int[n];
    for (int v = 0; v < n; v++) out[v] = find(parent, v);
    return out;
  }

  static int find(int[] parent, int x) {
    while (parent[x] != x) x = parent[x];
    return x;
  }
}
